// Guard + diff. This is what makes human-in-the-loop real:
// an unaddressed high-severity bias flag cannot be approved away.
const body = $('Webhook approve-review').first().json.body || {};
const row = $input.first().json;

if (!row || !row.id) {
  return [{ json: { __http_status: 404, ok: false, error: 'report_not_found', report_id: body.report_id } }];
}
if (row.status !== 'pending_approval') {
  return [{ json: { __http_status: 409, ok: false, error: 'already_finalized', status: row.status, reviewer: row.reviewer } }];
}

const action = body.action;
const reviewer = (body.reviewer || '').trim();
if (!['approved', 'rejected'].includes(action)) {
  return [{ json: { __http_status: 400, ok: false, error: 'invalid_action', detail: "action must be 'approved' or 'rejected'" } }];
}
if (!reviewer) {
  return [{ json: { __http_status: 400, ok: false, error: 'reviewer_required', detail: 'reviewer name is required for the audit trail' } }];
}

const draft = typeof row.draft_json === 'string' ? JSON.parse(row.draft_json) : row.draft_json;
const SECTIONS = ['strengths', 'growth_areas', 'impact_highlights', 'goal_progress'];
const edits = body.edits || {};

// Which points did the reviewer actually change?
const editedRefs = new Set();
const diff = [];
for (const section of SECTIONS) {
  const before = draft[section] || [];
  const after = edits[section];
  if (!Array.isArray(after)) continue;
  before.forEach((pt, i) => {
    const nt = after[i]?.text;
    if (nt !== undefined && nt !== pt.text) {
      editedRefs.add(`${section}[${i}]`);
      diff.push({ point_ref: `${section}[${i}]`, before: pt.text, after: nt });
    }
  });
  if (after.length < before.length) {
    for (let i = after.length; i < before.length; i++) {
      editedRefs.add(`${section}[${i}]`);
      diff.push({ point_ref: `${section}[${i}]`, before: before[i].text, after: null, removed: true });
    }
  }
}

// GUARD: block approval while any high-severity flag is unaddressed.
if (action === 'approved') {
  const unresolved = [];
  for (const section of SECTIONS) {
    (draft[section] || []).forEach((pt, i) => {
      const ref = `${section}[${i}]`;
      if (pt.flag && pt.flag.severity === 'high' && !(body.acknowledged_refs || []).includes(ref)) {
        const editedText = edits[section]?.[i]?.text;
        unresolved.push({ point_ref: ref, type: pt.flag.type, text: editedText || pt.text, reasoning: pt.flag.reasoning, edited: editedRefs.has(ref) });
      }
    });
  }
  if (unresolved.length) {
    return [{ json: {
      __http_status: 422,
      ok: false,
      error: 'unresolved_high_severity_flags',
      detail: 'Every high-severity flag must be explicitly acknowledged before approval. Editing alone does not prove that the issue was resolved.',
      unresolved_count: unresolved.length,
      unresolved
    } }];
  }
}

// Apply edits to produce the final report.
const final = JSON.parse(JSON.stringify(draft));
for (const section of SECTIONS) {
  const after = edits[section];
  if (!Array.isArray(after)) continue;
  final[section] = after.map((pt, i) => ({
    ...(draft[section]?.[i] || {}),
    ...pt,
    edited: draft[section]?.[i] ? pt.text !== draft[section][i].text : true
  }));
}
final.status = action;

return [{ json: {
  __http_status: 200,
  ok: true,
  report_id: row.id,
  employee_id: row.employee_id,
  action,
  reviewer,
  final,
  diff,
  acknowledged_refs: body.acknowledged_refs || [],
  edit_count: diff.length
} }];
